class Router:
    def __init__(self):
        self._routes = {}

    def register(self, method, path, handler):
        self._routes[(method, path)] = handler

    def handle(self, req):
        handler = self._routes.get((req.method, req.path))
        if handler is None:
            return 404
        if req.method == 'POST':
            return handler(req.body)
        return handler()


router = Router()

router.register('GET', '/users', get_users)
router.register('GET', '/posts', get_posts)
router.register('GET', '/comments', get_comments)
router.register('POST', '/users', create_user)
router.register('POST', '/posts', create_post)


def handle_request(req):
    return router.handle(req)

